public class InnerEvaluatorEvaluatorConfigFactory(Action<Humidifier.BedrockAgentCore.EvaluatorTypes.EvaluatorConfig> factoryAction = null) : SubResourceFactory<Humidifier.BedrockAgentCore.EvaluatorTypes.EvaluatorConfig>
{

    internal InnerEvaluatorCodeBasedEvaluatorConfigFactory CodeBasedFactory { get; set; }

    internal InnerEvaluatorLlmAsAJudgeEvaluatorConfigFactory LlmAsAJudgeFactory { get; set; }

    internal InnerEvaluatorDerivedEvaluatorConfigFactory DerivedFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.EvaluatorTypes.EvaluatorConfig Create()
    {
        var evaluatorConfigResult = CreateEvaluatorConfig();
        factoryAction?.Invoke(evaluatorConfigResult);

        return evaluatorConfigResult;
    }

    private Humidifier.BedrockAgentCore.EvaluatorTypes.EvaluatorConfig CreateEvaluatorConfig()
    {
        var evaluatorConfigResult = new Humidifier.BedrockAgentCore.EvaluatorTypes.EvaluatorConfig();

        return evaluatorConfigResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.EvaluatorTypes.EvaluatorConfig result)
    {
        base.CreateChildren(result);

        result.CodeBased ??= CodeBasedFactory?.Build();
        result.LlmAsAJudge ??= LlmAsAJudgeFactory?.Build();
        result.Derived ??= DerivedFactory?.Build();
    }

} // End Of Class

